import itertools
n=6
fixed={(3,5)}
# generate all triangle-free graphs and check maximal
verts=range(n)
edges_all=[(i,j) for i in verts for j in verts if i<j]

def is_triangle_free(edges):
    E=set(edges)
    for a,b,c in itertools.combinations(verts,3):
        if (a,b) in E and (a,c) in E and (b,c) in E:
            return False
    return True

def is_maximal(edges):
    E=set(edges)
    for e in edges_all:
        if e not in E:
            if is_triangle_free(list(E|{e})):
                return False
    return True

solutions=[]
for r in range(len(edges_all)+1):
    for combo in itertools.combinations(edges_all,r):
        if fixed.issubset(combo):
            if is_triangle_free(combo) and is_maximal(combo):
                solutions.append(combo)
                break
    if solutions:
        break
print('found',len(solutions))
if solutions:
    print(solutions[0])
